Repair the complete source below. Export the same API in the corrected complete source file. `CommandDecoder` receives a readonly mapping from two-digit hexadecimal opcodes to candidate command specifications. Each field has a non-empty name and an integer byte width from 1 through 6. `decodeFrame(frame)` accepts an even-length hexadecimal string containing at least an opcode byte, case-insensitively. Malformed input throws `TypeError`. It selects the sole candidate whose total field width equals the payload byte length; no match or multiple matches throws `Error`. Each field is decoded as an unsigned big-endian safe integer. Return copied field objects in specification order. Constructor inputs and results must not be mutated or aliased.

```typescript
export interface CommandField {
  readonly name: string;
  readonly bytes: number;
}

export interface CommandSpec {
  readonly name: string;
  readonly fields: readonly CommandField[];
}

export interface DecodedCommand {
  readonly name: string;
  readonly opcode: string;
  readonly fields: ReadonlyArray<{ name: string; value: number }>;
}

export class CommandDecoder {
  private readonly table: Readonly<Record<string, readonly CommandSpec[]>>;

  constructor(table: Readonly<Record<string, readonly CommandSpec[]>>) {
    const copy: Record<string, CommandSpec[]> = {};
    for (const [opcode, specs] of Object.entries(table)) {
      if (!/^[0-9a-fA-F]{2}$/.test(opcode)) throw new TypeError("Invalid opcode");
      copy[opcode.toUpperCase()] = specs.map((spec) => {
        if (spec.name.length === 0 || spec.fields.some((field) => field.name.length === 0 || !Number.isInteger(field.bytes) || field.bytes < 1 || field.bytes > 6)) {
          throw new TypeError("Invalid command specification");
        }
        return { name: spec.name, fields: spec.fields.map((field) => ({ ...field })) };
      });
    }
    this.table = copy;
  }

  decodeFrame(frame: string): DecodedCommand {
    if (frame.length < 2 || frame.length % 2 !== 0 || !/^[0-9a-fA-F]+$/.test(frame)) {
      throw new TypeError("Invalid frame");
    }
    const opcode = frame.slice(0, 2).toUpperCase();
    const payload = frame.slice(2);
    const matches = (this.table[opcode] ?? []).filter((spec) =>
      spec.fields.reduce((sum, field) => sum + field.bytes, 0) * 2 === payload.length,
    );
    if (matches.length !== 1) throw new Error("Command is unknown or ambiguous");
    const spec = matches[0];
    let cursor = 0;
    const fields = spec.fields.map((field) => {
      const hex = payload.slice(cursor, cursor + field.bytes * 2);
      cursor += field.bytes * 2;
      let value = 0;
      for (let index = hex.length - 2; index >= 0; index -= 2) {
        value = value * 256 + Number.parseInt(hex.slice(index, index + 2), 16);
      }
      return { name: field.name, value };
    });
    return { name: spec.name, opcode, fields };
  }
}
```

