import { CommandDecoder } from './solution';
import type { CommandField, CommandSpec, DecodedCommand } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError)) throw new Error(message);
}
function throwsError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof Error)) throw new Error(message);
}

const mutableFields: CommandField[] = [
  { name: 'short', bytes: 1 },
  { name: 'wide', bytes: 3 },
  { name: 'max', bytes: 6 },
];
const mutableSpecs: CommandSpec[] = [{ name: 'mixed', fields: mutableFields }];
const table: Record<string, readonly CommandSpec[]> = {
  aF: mutableSpecs,
  '10': [
    { name: 'empty', fields: [] },
    { name: 'one-byte', fields: [{ name: 'value', bytes: 1 }] },
  ],
  '20': [
    { name: 'candidate-one', fields: [{ name: 'x', bytes: 2 }] },
    { name: 'candidate-two', fields: [{ name: 'y', bytes: 2 }] },
  ],
};
const decoder = new CommandDecoder(table);
mutableFields[0] = { name: 'mutated', bytes: 6 };
mutableSpecs[0] = { name: 'changed', fields: [] };
table['aF'] = [];

const decoded = decoder.decodeFrame('af12abcdef010203040506');
equal(decoded.name, 'mixed', 'constructor copies command name and candidate');
equal(decoded.opcode, 'AF', 'opcode normalized to uppercase');
equal(decoded.fields.length, 3, 'all fields returned');
equal(decoded.fields[0].name, 'short', 'field name copied');
equal(decoded.fields[0].value, 0x12, 'one-byte field decoded');
equal(decoded.fields[1].value, 0xabcdef, 'multi-byte field decoded big-endian');
equal(decoded.fields[2].value, 0x010203040506, 'six-byte safe integer decoded big-endian');

const zeroPayload = decoder.decodeFrame('10');
equal(zeroPayload.name, 'empty', 'opcode-only frame matches zero-width specification');
equal(zeroPayload.fields.length, 0, 'zero-field result');
const oneByte = decoder.decodeFrame('10fF');
equal(oneByte.name, 'one-byte', 'payload width chooses sole candidate');
equal(oneByte.fields[0].value, 255, 'frame is case-insensitive');

(decoded.fields as Array<{ name: string; value: number }>)[0].name = 'result mutation';
(decoded.fields as Array<{ name: string; value: number }>)[1].value = 0;
const decodedAgain = decoder.decodeFrame('AF12ABCDEF010203040506');
equal(decodedAgain.fields[0].name, 'short', 'result fields do not alias decoder state');
equal(decodedAgain.fields[1].value, 0xabcdef, 'result value mutation does not affect later decode');
equal((decoded as DecodedCommand).opcode, 'AF', 'result remains ordinary decoded data');

throwsError(() => decoder.decodeFrame('99'), 'unknown opcode throws Error');
throwsError(() => decoder.decodeFrame('100001'), 'no width match throws Error');
throwsError(() => decoder.decodeFrame('200001'), 'multiple width matches throw Error');

throwsTypeError(() => decoder.decodeFrame(''), 'empty frame rejected');
throwsTypeError(() => decoder.decodeFrame('A'), 'odd-length frame rejected');
throwsTypeError(() => decoder.decodeFrame('0G'), 'non-hex frame rejected');
throwsTypeError(() => decoder.decodeFrame('100'), 'odd-length payload rejected');

throwsTypeError(() => new CommandDecoder({ G0: [] }), 'malformed opcode rejected');
throwsTypeError(() => new CommandDecoder({ '000': [] }), 'opcode must be exactly one byte');
throwsTypeError(() => new CommandDecoder({ AA: [{ name: '', fields: [] }] }), 'empty command name rejected');
throwsTypeError(
  () => new CommandDecoder({ AA: [{ name: 'x', fields: [{ name: '', bytes: 1 }] }] }),
  'empty field name rejected',
);
for (const bytes of [0, 7, 1.5, Number.NaN]) {
  throwsTypeError(
    () => new CommandDecoder({ AA: [{ name: 'x', fields: [{ name: 'field', bytes }] }] }),
    'field width outside integer range 1 through 6 rejected',
  );
}

